45|      scrollWidth: document.documentElement.scrollWidth,
46|      clientWidth: document.documentElement.clientWidth,
47|    }));
48|    expect(scrollWidth, `horizontal overflow: scrollWidth=${scrollWidth} > clientWidth=${clientWidth} + 1`).toBeLessThanOrEqual(
